"""Stage 94: the data structure chapter (docs/60, generated by tools/analyze_data_docs.py) is current, and the data it describes is consistent: every zero-page variable of the catalogue is a field of the C World, every member of every structure is a
catalogue variable, the structures and lifetimes cover what they should, and core/constants.h holds exactly the named constants of the table with the same values."""
import os
import re
import sys
import unittest

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
sys.path.insert(0, os.path.join(ROOT, "tools"))
import analyze_constants as C  # noqa: E402
import analyze_data_docs as D  # noqa: E402
import analyze_structures as S  # noqa: E402
import make_c_constants as MC  # noqa: E402
import make_c_world as MCW  # noqa: E402
import zp_catalogue as Z  # noqa: E402

DOC = os.path.join(ROOT, "docs", "60-data-structures.md")


class DataDocs(unittest.TestCase):
    def test_the_chapter_is_current(self):
        with open(DOC, encoding="utf-8", newline="") as fh:
            have = fh.read().replace("\r\n", "\n")
        self.assertEqual(have, D.doc(), "regenerate: python -I tools/analyze_data_docs.py --doc docs/60-data-structures.md")

    def test_every_catalogue_variable_is_a_field_of_the_world(self):
        fields = D.world_fields()
        self.assertEqual([z[2] for z in Z.ZP if z[2] not in fields], [])
        self.assertEqual(len(Z.ZP), 109)

    def test_every_structure_member_is_a_catalogue_variable(self):
        names = {z[2] for z in Z.ZP}
        for name, count, desc, members in S.STRUCTS:
            for m, ctype, vars_, d in members:
                for v, off in vars_:
                    self.assertIn(v, names, "%s.%s" % (name, m))
        self.assertEqual(len(S.STRUCTS), 14)

    def test_the_unused_zero_page_bytes_are_in_the_world_as_zp_xx(self):
        used = set()
        for a, n, *_ in Z.ZP:
            used |= set(range(a, a + n))
        fields = D.world_fields()
        unused = [a for a in range(256) if a not in used]
        self.assertEqual(len(used), 184)
        self.assertEqual(sum(1 for f in fields if re.match(r"zp_[0-9A-F]{2}$", f)), len(unused))

    def test_the_constants_header_is_the_table(self):
        with open(D.CONSTANTS_H, encoding="utf-8", newline="") as fh:
            have = fh.read().replace("\r\n", "\n")
        self.assertEqual(have, MC.text(), "regenerate: python -I tools/make_c_constants.py")
        header = D.constants_in_header()
        self.assertEqual(header.pop("PM_NAMED_CONSTANTS"), 51)
        self.assertEqual(header, {n: v for n, v, m, r, ch in C.NAMED})

    def test_the_c_uses_the_names_of_the_constants(self):
        """stage 94, the owner's readability pass: 50 of the 51 names are used in core/ and app/ (directly or through the aliases GHOST_*, PACMAN_*, REF_*); PMBASE_PAGE is the platform's"""
        used = set(D.used_names())
        self.assertEqual({n for n, *_ in C.NAMED} - used, {"PMBASE_PAGE"})

    def test_the_lookup_tables_of_the_core_are_all_described(self):
        tables = D.core_tables()
        self.assertEqual(len(tables), 18)
        self.assertTrue(all(c for n, c in tables), "every table has a description")

    def test_the_state_regions_are_the_ones_the_comparisons_use(self):
        self.assertEqual(256 + sum(e[2] for e in MCW.EXTRA), MCW.STATE_SIZE)


if __name__ == "__main__":
    unittest.main()
